#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <stdio.h>
#include <klee/klee.h>
#include "harness.c"

int main() {
    // Create a single dictionary and intentionally alias all globals to it
    AVDictionary *shared = (AVDictionary*)malloc(sizeof(AVDictionary));
    if (!shared) return 0;
    shared->count = 0;
    shared->alloc = 0;
    shared->elems = NULL;

    // Randomly decide which globals are aliased to the same object
    // This explores cases where 2-4 pointers alias the same heap object (double-free potential)
    unsigned char mask;
    klee_make_symbolic(&mask, sizeof(mask), "alias_mask");
    // Make sure at least two aliases happen to increase chance of double-free
    if ((mask & 3) == 0) mask |= 3;

    swr_opts   = (mask & 1) ? shared : NULL;
    sws_dict   = (mask & 2) ? shared : NULL;
    format_opts= (mask & 4) ? shared : NULL;
    codec_opts = (mask & 8) ? shared : NULL;

    uninit_opts();
    return 0;
}

