// Minimal AVClass
typedef struct AVClass {
    const void *option; // any non-NULL indicates options exist
} AVClass;

// Stubs for libavutil option API used by show_help_children
static void av_opt_show2(const AVClass **classp, void *obj, int flags, int req)
{
    // Minimal: print something
    (void)obj; (void)flags; (void)req;
    // Access *classp to keep behavior realistic
    if (classp && *classp && (*classp)->option)
        printf("class has options\n");
}

static const AVClass *av_opt_child_class_iterate(const AVClass *classp, void **iter)
{
    // Iterate over a provided single child stored in *iter just once
    if (!iter)
        return NULL;
    const AVClass *ret = (const AVClass*)(*iter);
    *iter = NULL; // next time return NULL
    return ret;
}

// Target from cmdutils.c
void show_help_children(const AVClass *class, int flags)
{
    void *iter = NULL;
    const AVClass *child;
    if (class->option) {
        av_opt_show2(&class, NULL, flags, 0);
        printf("\n");
    }

    while (child = av_opt_child_class_iterate(class, &iter))
        show_help_children(child, flags);
}

