// Minimal StreamSpecifier (from header)
enum AVMediaType { AVMEDIA_TYPE_UNKNOWN = -1 };
enum StreamList { STREAM_LIST_ALL, STREAM_LIST_STREAM_ID, STREAM_LIST_PROGRAM, STREAM_LIST_GROUP_ID, STREAM_LIST_GROUP_IDX };

typedef struct StreamSpecifier {
    int                  idx;
    enum StreamList      stream_list;
    int64_t              list_id;
    enum AVMediaType     media_type;
    uint8_t              no_apic;
    uint8_t              usable_only;
    int                  disposition;
    char                *meta_key;
    char                *meta_val;
    char                *remainder;
} StreamSpecifier;

static void av_freep(void *ptr)
{
    void **p = (void**)ptr;
    if (p && *p) {
        free(*p);
        *p = NULL;
    }
}

// Target prototype in API: void stream_specifier_uninit(StreamSpecifier *ss);
void stream_specifier_uninit(StreamSpecifier *ss)
{
    if (!ss)
        return;
    av_freep(&ss->meta_key);
    av_freep(&ss->meta_val);
    av_freep(&ss->remainder);
}

