// driver.c
#include <stdlib.h>
#include <stdint.h>
#include <klee/klee.h>
#include "harness.c"

int main() {
    StreamSpecifier ss;
    memset(&ss, 0, sizeof(ss));

    // Intentionally alias fields to the same allocated buffer to trigger double-free
    char *buf = (char*)malloc(8);
    klee_make_symbolic(buf, 8, "buf");

    unsigned char alias_mode;
    klee_make_symbolic(&alias_mode, sizeof(alias_mode), "alias_mode");

    if (alias_mode & 1) {
        ss.meta_key = buf;
        ss.meta_val = buf;  // alias
    } else {
        ss.meta_key = buf;
        ss.meta_val = (char*)malloc(8);
    }
    if (alias_mode & 2) {
        ss.remainder = ss.meta_key; // may alias too
    } else {
        ss.remainder = (char*)malloc(8);
    }

    stream_specifier_uninit(&ss);
    return 0;
}

