// Minimal AVDictionary model
typedef struct AVDictionaryEntry { char *key; char *value; } AVDictionaryEntry;

typedef struct AVDictionary {
    int count;
    int alloc;
    AVDictionaryEntry *elems;
} AVDictionary;

static int av_dict_count(const AVDictionary *d) { return d ? d->count : 0; }

// Target: remove_avoptions(AVDictionary **a, AVDictionary *b)
// Remove from *a any keys that exist in b
void remove_avoptions(AVDictionary **a, AVDictionary *b)
{
    if (!a || !*a || !b)
        return;
    AVDictionary *A = *a;
    for (int i = 0; i < b->count; i++) {
        char *keyb = b->elems[i].key; // may OOB if b->count > b->alloc
        if (!keyb) continue;
        for (int j = 0; j < A->count; j++) {
            if (A->elems[j].key && strcmp(A->elems[j].key, keyb) == 0) {
                free(A->elems[j].key);
                free(A->elems[j].value);
                // shift remaining elements left by 1
                if (j + 1 < A->count)
                    memmove(&A->elems[j], &A->elems[j+1], (A->count - j - 1) * sizeof(A->elems[0]));
                A->count--;
                j--;
            }
        }
    }
}

