} AVDictionary;

// Target: int check_avoptions(AVDictionary *m);
// Simplified: return -1 if any entry has NULL key or value, else 0
int check_avoptions(AVDictionary *m)
{
    if (!m)
        return 0;
    int bad = 0;
    for (int i = 0; i < m->count; i++) {
        // Potential OOB if m->count > m->alloc
        if (!m->elems[i].key || !m->elems[i].value)
            bad++;
    }
    return bad ? -1 : 0;
}

