#include <stdlib.h>
#include <stdint.h>
#include <string.h>

// Minimal OptionDef
typedef struct OptionDef {
    const char *name;
    int flags;
    const char *argname;
    const char *help;
} OptionDef;

// Target: int locate_option(int argc, char **argv, const OptionDef *options, const char *optname);
// Simplified implementation: find index of first argv[i] that matches any options[j].name or optname
int locate_option(int argc, char **argv, const OptionDef *options, const char *optname)
{
    // Scan argv
    for (int i = 0; i < argc; i++) {
        const char *a = argv[i];
        if (!a) continue;
        // Compare against provided optname
        if (optname && strcmp(a, optname) == 0)
            return i;
        // Compare against options[] until sentinel name==NULL
        for (int j = 0; ; j++) {
            // Potential OOB if options is not properly NULL-terminated
            const char *on = options[j].name;
            if (!on)
                break;
            if (strcmp(a, on) == 0)
                return i;
        }
    }
    return -1;
}

