void log_callback_help(void* ptr, int level, const char* fmt, va_list vl)
{
    (void)ptr; (void)level;
    vfprintf(stdout, fmt, vl);
}

// Small wrapper to pass varargs into log_callback_help
void call_log_callback(void *ptr, int level, const char *fmt, ...) {
    va_list vl;
    va_start(vl, fmt);
    log_callback_help(ptr, level, fmt, vl);
    va_end(vl);
}

